/**
 * Error model. Every failure the client can see is an AppError with a stable
 * machine code; provider errors, SQL text and stack traces never reach the
 * response body (spec SEC-05, section 20).
 */

export type ErrorCode =
  | 'bad_request'
  | 'validation_failed'
  | 'unauthenticated'
  | 'mfa_required'
  | 'reauth_required'
  | 'forbidden'
  | 'not_found'
  | 'conflict'
  | 'version_conflict'
  | 'payload_too_large'
  | 'rate_limited'
  | 'quota_exceeded'
  | 'write_frozen'
  | 'upstream_unavailable'
  | 'internal'

const STATUS: Record<ErrorCode, number> = {
  bad_request: 400,
  validation_failed: 400,
  unauthenticated: 401,
  mfa_required: 401,
  reauth_required: 401,
  forbidden: 403,
  not_found: 404,
  conflict: 409,
  version_conflict: 409,
  payload_too_large: 413,
  rate_limited: 429,
  quota_exceeded: 429,
  write_frozen: 503,
  upstream_unavailable: 503,
  internal: 500,
}

/** Field-level validation detail, keyed by input path. */
export type FieldErrors = Record<string, string>

export class AppError extends Error {
  readonly code: ErrorCode
  readonly status: number
  readonly fieldErrors?: FieldErrors
  readonly retryAfter?: number
  /** Extra detail that is safe to show the client. */
  readonly detail?: Record<string, unknown>

  constructor(
    code: ErrorCode,
    message: string,
    options: { fieldErrors?: FieldErrors; retryAfter?: number; detail?: Record<string, unknown>; cause?: unknown } = {},
  ) {
    super(message, options.cause === undefined ? undefined : { cause: options.cause })
    this.name = 'AppError'
    this.code = code
    this.status = STATUS[code]
    this.fieldErrors = options.fieldErrors
    this.retryAfter = options.retryAfter
    this.detail = options.detail
  }
}

export const badRequest = (message: string, fieldErrors?: FieldErrors) =>
  new AppError('bad_request', message, { fieldErrors })

export const invalid = (fieldErrors: FieldErrors, message = '입력값을 확인해 주세요.') =>
  new AppError('validation_failed', message, { fieldErrors })

export const unauthenticated = (message = '로그인이 필요합니다.') =>
  new AppError('unauthenticated', message)

export const forbidden = (message = '권한이 없습니다.') => new AppError('forbidden', message)

/** Hides existence of a resource the caller may not see (spec section 18). */
export const notFound = (message = '대상을 찾을 수 없습니다.') => new AppError('not_found', message)

export const conflict = (message: string, detail?: Record<string, unknown>) =>
  new AppError('conflict', message, { detail })

export const versionConflict = (message = '다른 곳에서 먼저 변경되었습니다. 새로 불러온 뒤 다시 시도해 주세요.') =>
  new AppError('version_conflict', message)

export const rateLimited = (message: string, retryAfter: number) =>
  new AppError('rate_limited', message, { retryAfter })

export const quotaExceeded = (message: string, detail?: Record<string, unknown>) =>
  new AppError('quota_exceeded', message, { detail })

export const upstreamUnavailable = (message = '외부 서비스에 일시적인 문제가 있습니다. 잠시 후 다시 시도해 주세요.') =>
  new AppError('upstream_unavailable', message)

export const internal = (message = '처리 중 문제가 발생했습니다.', cause?: unknown) =>
  new AppError('internal', message, { cause })

/** True when err is a Postgres unique-constraint violation. */
export function isUniqueViolation(err: unknown): boolean {
  return typeof err === 'object' && err !== null && (err as { code?: string }).code === '23505'
}

/** The constraint name a unique violation fired on, when the driver reports it. */
export function violatedConstraint(err: unknown): string {
  if (typeof err !== 'object' || err === null) return ''
  return String((err as { constraint_name?: string; constraint?: string }).constraint_name ??
    (err as { constraint?: string }).constraint ?? '')
}

/** True when the failure is a Postgres RLS / privilege denial. */
export function isPermissionDenied(err: unknown): boolean {
  if (typeof err !== 'object' || err === null) return false
  const code = String((err as { code?: string }).code ?? '')
  return code === '42501'
}

/** True when the failure is a serialisation conflict worth retrying. */
export function isSerializationFailure(err: unknown): boolean {
  if (typeof err !== 'object' || err === null) return false
  const code = String((err as { code?: string }).code ?? '')
  return code === '40001' || code === '40P01'
}

/**
 * A connection that went away underneath a query.
 *
 * Expected rather than exceptional in this deployment. Each request builds its
 * own pool, several requests share an isolate, and every connection runs
 * through Cloudflare's pooler - which closes one when the Worker is holding
 * more than its share. The query never reached the database, so running it
 * again on a fresh connection is correct and is not a retry of a partial
 * write.
 *
 * Observed as intermittent 500s on plain GETs: roughly one request in twelve
 * under ten concurrent callers, with
 * "write CONNECTION_CLOSED <id>.hyperdrive.local:5432".
 */
export function isConnectionLost(err: unknown): boolean {
  if (typeof err !== 'object' || err === null) return false
  const code = String((err as { code?: string }).code ?? '')
  if (
    code === 'CONNECTION_CLOSED' ||
    code === 'CONNECTION_ENDED' ||
    code === 'CONNECTION_DESTROYED' ||
    code === 'CONNECTION_CONNECT_TIMEOUT' ||
    code === 'ECONNRESET' ||
    code === 'EPIPE' ||
    // SQLSTATE class 08 (connection exception), 57P01-03 (the server ending or
    // refusing sessions), 58000 (Hyperdrive's own errors, e.g. no free origin
    // connection), 53300 (no free connection slot - frees a moment later).
    /^(08\w{3}|57P0[123]|58000|53300)$/.test(code)
  ) {
    return true
  }
  // postgres.js reports some of these only in the message. EMAXCONNSESSION is
  // the pooler refusing a new client because every slot is taken - contention,
  // not a fault, and the statement never ran, so a moment later it succeeds.
  // "Network connection lost." is how Workers reports a socket that dropped.
  const message = String((err as { message?: string }).message ?? '')
  return /CONNECTION_(CLOSED|ENDED|DESTROYED)|ECONNRESET|socket hang up|EMAXCONNSESSION|max clients reached|network connection lost|connection terminated|failed to acquire a connection|pool_capacity|too many connections|remaining connection slots/i.test(
    message,
  )
}
/**
 * The request pipeline.
 *
 * Order matters:
 *   route match -> body limit -> principal -> auth mode -> scopes -> AAL
 *   -> same-origin + CSRF -> write freeze -> transaction -> audit
 *
 * The same order as yeopjari's; what was dropped is what this service does not
 * have (API keys, OAuth, a heavy runtime). What was added is `bare` routes,
 * which skip everything after the route match.
 */
import { Database, elevate, type DbContext, type Sql } from '../db.js'
import type { Env } from '../env.js'
import { timingSafeEqual } from '../util/crypto.js'
import { AppError, forbidden, badRequest, isPermissionDenied, unauthenticated } from '../errors.js'
import { writeAudit } from '../audit.js'
import { missingScopes } from '../auth/scopes.js'
import type { ScopeResolver } from '../auth/scopes.js'
import { csrfMatches } from '../auth/session.js'
import { CSRF_HEADER, SESSION_HINT_HEADER, readCookies, sessionCookieName } from '../auth/cookies.js'
import { hashClient, resolvePrincipal } from '../auth/principal.js'
import type { Settings } from '../settings/service.js'
import { errorResponse, json, NO_STORE } from './respond.js'
import type { Router } from './router.js'
import { Mailer } from '../mail/mailer.js'
import { serviceErrorMail } from '../mail/templates.js'
import { ANONYMOUS_PRINCIPAL, type Ctx, type Method, type Route } from './types.js'

export interface PipelineDeps {
  env: Env
  db: Database
  settings: Settings
  scopes: ScopeResolver
  router: Router
  /** Runs after-commit work; App.close waits for it. */
  background: Background
}

/** Work started after a response's transaction committed, tracked so shutdown can wait for it. */
export class Background {
  private readonly pending = new Set<Promise<unknown>>()

  run(label: string, task: () => Promise<unknown>): void {
    const running = Promise.resolve()
      .then(task)
      .catch((err: unknown) => {
        console.error(JSON.stringify({ level: 'error', message: 'after-commit task failed', task: label, detail: String(err) }))
      })
      .finally(() => this.pending.delete(running))
    this.pending.add(running)
  }

  /** Resolves when everything started so far (and anything it started) is done. */
  async settled(): Promise<void> {
    while (this.pending.size > 0) await Promise.allSettled([...this.pending])
  }
}

/** Largest JSON body accepted on a normal API route. */
const MAX_JSON_BYTES = 128 * 1024
/** Largest raw body accepted at all. */
const MAX_RAW_BYTES = 256 * 1024

const SAFE_METHODS = new Set<Method>(['GET', 'HEAD', 'OPTIONS'])

export async function handleRequest(deps: PipelineDeps, request: Request): Promise<Response> {
  return hardened(await dispatchRequest(deps, request))
}

/**
 * Headers every API response carries, whatever produced it.
 *
 * Nothing under the API is a page, yet any response can be opened as one - an
 * export or a CSV pasted into the location bar is rendered as a document on
 * this origin. The policy gives such a document no script, no network and no
 * origin, so even a hostile file would be inert. It costs nothing for JSON.
 */
export const API_DOCUMENT_POLICY =
  "default-src 'none'; style-src 'unsafe-inline'; img-src data:; frame-ancestors 'none'; sandbox"

function hardened(response: Response): Response {
  const headers = new Headers(response.headers)
  headers.set('x-content-type-options', 'nosniff')
  if (!headers.has('content-security-policy')) headers.set('content-security-policy', API_DOCUMENT_POLICY)
  headers.set('x-frame-options', 'DENY')
  headers.set('cross-origin-resource-policy', 'same-origin')
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers })
}

async function dispatchRequest(deps: PipelineDeps, request: Request): Promise<Response> {
  const requestId = crypto.randomUUID()
  const url = new URL(request.url)
  const method = request.method.toUpperCase() as Method

  try {
    const matched = deps.router.match(method, url.pathname)
    if (!matched) {
      return errorResponse(new AppError('not_found', '요청한 경로가 없습니다.'), requestId)
    }
    if ('allow' in matched) {
      if (method === 'OPTIONS') {
        return new Response(null, {
          status: 204,
          headers: { allow: [...matched.allow, 'OPTIONS'].join(', '), 'cache-control': NO_STORE },
        })
      }
      return json(
        { error: { code: 'bad_request', message: '허용되지 않은 메서드입니다.' }, request_id: requestId },
        { status: 405, headers: { allow: [...matched.allow, 'OPTIONS'].join(', ') } },
      )
    }

    const { route, params } = matched
    if (route.bare) return await runBare(deps, { request, url, method, route, params, requestId })
    return await runRoute(deps, { request, url, method, route, params, requestId })
  } catch (caught) {
    // A row policy or guard trigger said no. The routes check first and say
    // why in words; reaching this means a race or someone trying the door.
    const err = isPermissionDenied(caught) ? forbidden('이 작업을 할 수 없어요.') : caught
    if (err !== caught) {
      console.warn(JSON.stringify({ level: 'warn', message: 'row policy refused', request_id: requestId, method, path: normalisePath(url.pathname), detail: String((caught as Error).message ?? '').slice(0, 200) }))
    }
    logFailure(deps.env, requestId, url.pathname, method, err)
    // Awaited rather than left dangling: on a serverless runtime the isolate
    // can be torn down the moment the response is returned. Throttled to one
    // mail per distinct failure per window.
    await alertOperator(deps, requestId, url.pathname, method, err)
    return errorResponse(err, requestId)
  }
}

/**
 * The route, not the request: /api/v1/profiles/<uuid> failing for two
 * different ids is one fault, and must open one alert.
 */
export function normalisePath(path: string): string {
  return path
    .replace(/\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, '/:id')
    .replace(/\/\d+(?=\/|$)/g, '/:n')
    .replace(/\/p\/[A-Za-z0-9_.-]{20,}/g, '/p/:token')
}

/**
 * Mails the operator about a failure the service could not handle. Never
 * throws: a fault in the alerting path must not become a second fault.
 */
export async function alertOperator(
  deps: PipelineDeps,
  requestId: string,
  path: string,
  method: string,
  err: unknown,
): Promise<void> {
  try {
    if (err instanceof AppError && err.status < 500) return
    if (err instanceof AppError && err.code === 'write_frozen') return

    const s = await deps.settings.pick(
      'ops.error_alert_enabled',
      'ops.error_alert_to',
      'ops.error_alert_window_minutes',
      'brand.support_email',
      'brand.display_name',
    )
    if (!s['ops.error_alert_enabled']) return
    const to = (s['ops.error_alert_to'] || s['brand.support_email']).trim()
    if (!to) return

    const code = err instanceof AppError ? err.code : 'internal'
    const message = redactSecrets(err instanceof Error ? err.message : String(err))
    const signature = `${method} ${normalisePath(path)} ${code}`

    const rows = await deps.db.internal((sql: Sql) =>
      elevate(sql, (tx) => tx<{ send: boolean; occurrences: number; first_seen_at: Date }[]>`
        SELECT insight_priv.record_error_alert(
                 ${signature}, ${method}, ${normalisePath(path)}, ${code}, ${message}, ${requestId},
                 ${s['ops.error_alert_window_minutes']}) AS send,
               (SELECT occurrences FROM insight_priv.error_alerts WHERE signature = ${signature}) AS occurrences,
               (SELECT first_seen_at FROM insight_priv.error_alerts WHERE signature = ${signature}) AS first_seen_at`),
    )
    const row = rows[0]
    if (!row?.send) return

    const mailer = new Mailer(deps.env, { enabled: true, fromName: s['brand.display_name'] })
    await mailer.send(
      serviceErrorMail(
        { displayName: s['brand.display_name'], publicUrl: deps.env.publicUrl },
        {
          to,
          method,
          path: normalisePath(path),
          code,
          message: message.slice(0, 300),
          requestId,
          occurrences: row.occurrences ?? 1,
          firstSeenAt: (row.first_seen_at ?? new Date()).toISOString().replace('T', ' ').slice(0, 19),
          windowMinutes: s['ops.error_alert_window_minutes'],
        },
      ),
    )
  } catch {
    // The service is already failing; a failure to say so changes nothing.
  }
}

interface RunInput {
  request: Request
  url: URL
  method: Method
  route: Route
  params: Record<string, string>
  requestId: string
}

/** A route that needs nothing from the database to answer. */
async function runBare(deps: PipelineDeps, input: RunInput): Promise<Response> {
  const { request, url, method, route, params, requestId } = input
  const ctx = {
    env: deps.env,
    db: deps.db,
/**
 * Cloudflare Pages Function adapter.
 *
 * Catches every request that is not a static asset and hands it to the same
 * application the offline container runs. What is specific to this runtime:
 *
 *   - The database is reached through Hyperdrive (Cloudflare's pooler at the
 *     edge); the driver cannot complete its own TLS handshake under workerd.
 *   - Everything is built per request: a socket opened for one request cannot
 *     be used by another ("Cannot perform I/O on behalf of a different
 *     request"). Finished values - settings and permission snapshots - are
 *     shared at module level by the core instead.
 *   - The one response every visitor fetches first, the public configuration,
 *     is kept at the edge for half a minute.
 *
 * The same shape as yeopjari's adapter, minus what this service does not have.
 */
import { Database, createApp, useMailGateway, type App, type MailGateway } from '@insight/core'

interface Env {
  HYPERDRIVE?: { connectionString: string }
  INSIGHT_DATABASE_URL: string
  INSIGHT_PUBLIC_URL: string
  INSIGHT_SESSION_KEY: string
  INSIGHT_SECRETS_KEY: string
  INSIGHT_MAIL_HMAC_KEY: string
  INSIGHT_CODE_HMAC_KEY: string
  INSIGHT_TOKEN_SIGN_KEY: string
  INSIGHT_INTERNAL_KEY: string
  /** 'direct' bypasses Hyperdrive and connects to the pooler itself. */
  INSIGHT_DB_VIA?: string
  INSIGHT_MAIL_DRIVER?: string
  INSIGHT_MAIL_FROM?: string
  RESEND_API_KEY?: string
  /** The account-wide mail gateway Worker (wrangler.toml [[services]]): Resend, then Cloudflare past the quota. */
  MAIL?: MailGateway
  INSIGHT_YEOPJARI_URL?: string
  INSIGHT_YEOPJARI_CLIENT_ID?: string
  INSIGHT_YEOPJARI_CLIENT_SECRET?: string
  INSIGHT_VERSION?: string
  INSIGHT_COMMIT?: string
}

/** Statements sent per request, reported in Server-Timing: the latency is their count. */
interface Meter {
  statements: number
  sentAt: number[]
  started: number
}

function build(env: Env, meter?: Meter): App {
  const hyperdrive = env.INSIGHT_DB_VIA === 'direct' ? undefined : env.HYPERDRIVE
  const url = hyperdrive?.connectionString ?? env.INSIGHT_DATABASE_URL
  const database = new Database(url, {
    // Hyperdrive's address is inside the runtime and will not do TLS.
    ...(hyperdrive ? { ssl: false as const } : { ssl: 'require' as const }),
    // More than one: a handler's transaction and a system-phase call (issuing
    // a session, say) run on separate connections at once.
    max: 4,
    idleTimeout: 20,
    connectTimeout: 10,
    prepare: false,
    // The shared database's gateway login: every transaction switches to this role.
    role: typeof env.INSIGHT_DB_ROLE === 'string' && env.INSIGHT_DB_ROLE !== '' ? env.INSIGHT_DB_ROLE : undefined,
    onStatement: meter
      ? () => {
          meter.statements += 1
          meter.sentAt.push(Date.now() - meter.started)
        }
      : undefined,
  })
  return createApp({ ...env, INSIGHT_DATABASE_URL: url } as unknown as Record<string, string | undefined>, {
    database,
    maxConnections: 4,
    prepare: false,
  })
}

/**
 * What a messenger shows when a link is pasted. Static per route: a link
 * preview is shown to whoever the link reaches, so nothing about a member may
 * ever be in one.
 */
interface Preview {
  title: string
  description: string
}

const DEFAULT_PREVIEW: Preview = {
  title: '옆자리 인사이트 · 회사 인증된 직장인과 함께하는 리서치',
  description: '일하는 사람의 경험이 제품을 바꿉니다. 인터뷰·사용성 테스트·설문에 참여하고 보상을 받으세요.',
}

const PREVIEWS: [RegExp, Preview][] = [
  [/^\/studies\/?$/, { title: '모집 중인 연구 · 옆자리 인사이트', description: '회사 인증을 마친 직장인을 찾는 인터뷰·사용성 테스트·설문이에요. 내 회사가 의뢰한 연구는 보이지 않아요.' }],
  [/^\/studies\/[0-9a-f-]{36}$/, { title: '참여자를 찾는 연구 · 옆자리 인사이트', description: '조건이 맞으면 옆자리 계정으로 바로 신청할 수 있어요. 기업에는 이름 대신 코드명만 전달돼요.' }],
  [/^\/for-teams(\/|$)/, { title: '기업 리서치 · 옆자리 인사이트', description: '원하는 직무의 실무자에게 직접 듣는 제품 피드백. 회사 인증 직장인 모집부터 진행·보상까지 맡기세요.' }],
  [/^\/(login|start)(\/|$)/, { title: '시작하기 · 옆자리 인사이트', description: '옆자리 계정으로 1분이면 시작해요. 회사 인증이 그대로 이어져요.' }],
  [/^\/team\/login\/?$/, { title: '의뢰 기업 로그인 · 옆자리 인사이트', description: '등록된 업무용 메일로 로그인 코드를 받아 들어와요.' }],
  [/^\/privacy\/?$/, { title: '개인정보 처리방침 · 옆자리 인사이트', description: '필요한 만큼만 받고, 기업에는 이름 대신 연구마다 다른 코드명으로만 전달해요.' }],
]

function previewFor(pathname: string): Preview {
  for (const [pattern, preview] of PREVIEWS) if (pattern.test(pathname)) return preview
  return DEFAULT_PREVIEW
}

function escapeAttribute(value: string): string {
  return value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
}

