/** A study of one of the caller's companies, with its brief and controls. */
async function loadStudy(ctx: Ctx, id: string, orgIds: string[]): Promise<ClientStudyRow> {
  const rows = await ctx.sql<ClientStudyRow[]>`
    SELECT ${ctx.sql.unsafe(STUDY_COLUMNS)}, o.name AS org_name,
           b.task_brief, b.task_links, b.meeting_url, b.submission_form,
           c.screener_rules, c.review_note, c.quote_amount, c.billing_status
    FROM insight.studies s
    JOIN insight.orgs o ON o.id = s.org_id
    LEFT JOIN insight.study_briefs b ON b.study_id = s.id
    LEFT JOIN insight.study_controls c ON c.study_id = s.id
    WHERE s.id = ${id}`
  const row = rows[0]
  // The policy already hides other companies' studies; this is belt and braces.
  if (!row || !orgIds.includes(row.org_id)) throw notFound('연구를 찾을 수 없어요.')
  return row
}

