/**
 * A researcher acting for one client company. Membership is read under the
 * caller's own policy (their own rows), so nothing here widens what they see.
 */
export async function requireResearcher(ctx: Ctx): Promise<{ accountId: string; orgIds: string[] }> {
  const accountId = requireAccount(ctx)
  if (ctx.principal.status !== 'approved') throw forbidden('이용할 수 없는 계정입니다.')
  const rows = await ctx.sql<{ org_id: string }[]>`
    SELECT m.org_id FROM insight.org_members m
    JOIN insight.orgs o ON o.id = m.org_id
    WHERE m.account_id = ${accountId} AND o.status = 'active'`
  if (rows.length === 0) throw forbidden('의뢰 기업 담당자만 쓸 수 있어요.')
  return { accountId, orgIds: rows.map((r) => r.org_id) }
}

